+    final sub = rest.trim();
+    switch (sub) {
+      case '':
+        final pending = await _subagentManager.pendingInboxCount(
+          _subagentManager.selfId,
+        );
+        final spend = guard == null
+            ? null
+            : '${guard.tokensSpent}'
